_BOLD = dict(zip(CHARS, BOLD))


def width(text: str, size: float, bold: bool = False) -> float:
    """Ширина строки в пикселях при размере шрифта size (как в стиле ASS)."""
    table = _BOLD if bold else _REG
    default = 1382 if bold else 1255
    return sum(table.get(ch, default) for ch in text) * size / _UNITS


def wrap(text: str, size: float, max_width: float, bold: bool = False) -> list[list[str]]:
    """Жадный перенос по словам: список строк, каждая - список слов. Слово длиннее строки остаётся целым на своей строке."""
    lines: list[list[str]] = []
    for para in text.split("\n"):
        cur: list[str] = []
        for w in para.split():
            cand = " ".join(cur + [w])
            if cur and width(cand, size, bold) > max_width:
                lines.append(cur)
                cur = [w]
            else:
                cur.append(w)
        if cur:
            lines.append(cur)
    return lines
